import numpy as np
import json

# Correct block cells for TEST INPUT:
# Block 1: rows 3-4, cols 3-4
# Block 2: rows 5-6, cols 1-2
block_cells = {(3,3), (3,4), (4,3), (4,4), (5,1), (5,2), (6,1), (6,2)}

output = np.zeros((8,8), dtype=int)

# Fill 2x2 blocks
for r, c in block_cells:
    output[r, c] = 2

# Main diagonal r-c=0: 8 upper (r<=3), 6 lower (r>3)
for rr in range(8):
    cc = rr
    if (rr, cc) not in block_cells:
        if rr <= 3:
            output[rr, cc] = 8
        else:
            output[rr, cc] = 6

# Anti diagonal r+c=7: 3 upper (r<=3), 7 lower (r>3)
for rr in range(8):
    cc = 7 - rr
    if (rr, cc) not in block_cells:
        if rr <= 3:
            output[rr, cc] = 3
        else:
            output[rr, cc] = 7

print("Corrected output:")
for row in output:
    print(" ".join(f"{x}" if x != 0 else "." for x in row))

# Verify blocks
print(f"\nBlock cells with value 2: {sorted([(r,c) for r in range(8) for c in range(8) if output[r,c]==2])}")

